        baseline: Digest32,
        candidate: Digest32,
        mode: ObservationMode,
        changed_candidate_action: bool,
        decision_binding: DecisionBinding,
    ) -> anyhow::Result<()> {
        let rule = self.rule.clone();
        let history_at = rule.history_start_unix_seconds + 10;
