                .execute(
                    previous,
                    input.clone(),
                    baseline,
                    /*selected_index*/ 0,
                    rule.candidate_plan.fold.evaluation_start,
                )
                .await?;
            material::evaluation_provider::decision(
                self.writer.as_mut().expect("original B ledger"),
                &self.credentials,
                &target.episode.episode_id,
                &publication,
                rule.candidate_plan.fold.evaluation_start,
